using Godot;
using System;
using GArray=Godot.Collections.Array;
using Settings=Godot.Collections.Dictionary;
public partial class DestructionVfxOperations:RefCounted
{
    private readonly DestructionMaterialOperations _materials=new();private readonly ActorAnimationOperations _animation=new();private static Settings Map(GodotObject owner,string key)=>owner.Get(key).AsGodotDictionary();private static Variant Get(Settings values,string key,Variant fallback=default)=>values.TryGetValue(key,out var value)?value:fallback;
    public void reset(RefCounted owner){foreach(var value in Map(owner,"nodes").Values){var node=value.AsGodotObject() as Node;if(GodotObject.IsInstanceValid(node))node!.Free();}Map(owner,"nodes").Clear();Map(owner,"resources").Clear();}
    private static Settings Rule(int style,Color color,double size,double velocity,Vector3 gravity,double amount,double life)=>new(){["style"]=style,["color"]=color,["particle_size"]=size,["velocity"]=velocity,["gravity"]=gravity,["amount"]=amount,["lifetime"]=life};
    public GArray rules(Settings values){var material=_materials.resolve(values,Vector3.Zero);var raw=material!=null?Get(material.Get("values").AsGodotDictionary(),"vfx_family",0):Variant.From(0);int family=raw.VariantType is Variant.Type.Int or Variant.Type.Float?raw.AsInt32():0;if(family==0&&material!=null){string name=Get(material.Get("values").AsGodotDictionary(),"material_name","").AsString().ToLowerInvariant();family=name.Contains("glass",StringComparison.Ordinal)||name.Contains("ceramic",StringComparison.Ordinal)?1:name.Contains("steel",StringComparison.Ordinal)||name.Contains("aluminum",StringComparison.Ordinal)||name.Contains("metal",StringComparison.Ordinal)?2:name.Contains("wood",StringComparison.Ordinal)?3:4;}var result=new GArray();switch(family){case 1:result.Add(Rule(1,new Color(.7f,.9f,1,.8f),.025,2,new Vector3(0,-9.8f,0),1,1));break;case 2:result.Add(Rule(3,new Color(1,.65f,.15f),.03,4,new Vector3(0,-5,0),.7,.6));break;case 3:result.Add(Rule(2,new Color(.5f,.25f,.09f),.04,2,new Vector3(0,-9.8f,0),.7,1));result.Add(Rule(0,new Color(.6f,.4f,.2f,.25f),.12,.8,new Vector3(0,-.2f,0),.3,1));break;default:result.Add(Rule(0,new Color(.55f,.52f,.46f,.28f),.18,.8,new Vector3(0,.2f,0),1,1));result.Add(Rule(1,new Color(.4f,.38f,.34f),.035,2,new Vector3(0,-9.8f,0),.35,.8));break;}var reference=Get(values,"debris_vfx_preset");if(reference.VariantType==Variant.Type.Nil&&material!=null)reference=Get(material.Get("values").AsGodotDictionary(),"vfx_preset");var resource=reference.VariantType==Variant.Type.Object?reference.AsGodotObject() as Resource:null;var preset=ActorDataOperations.ScriptIs(resource,"res://scripts/actors/core/actor_object_reference.gd")?_animation.resolve_reference(resource!):null;if(preset!=null){if(Get(values,"debris_vfx_mode",0).AsInt32()==0)result.Clear();result.Add(preset.Get("values").AsGodotDictionary().Duplicate());}return result;}
    public GArray particles(Settings impact,Settings rule,Settings values,double time,int limit){var result=new GArray();double age=(time-impact["time"].AsDouble())*Get(impact,"age_scale",1).AsDouble(),life=Math.Clamp(Get(values,"debris_lifetime",2).AsDouble()*Get(rule,"lifetime",1).AsDouble(),.05,10);if(age<0||age>life||!Get(values,"debris_vfx_enabled",true).AsBool())return result;int style=Get(rule,"style",0).AsInt32();double energy=impact["energy"].AsDouble();if(style==3&&(energy<2||impact["type"].AsString() is "fracture" or "secondary"))return result;if(style==0&&energy<.5)return result;double intensity=Math.Clamp(Math.Log(1+energy)*.3*Get(values,"debris_intensity",1).AsDouble(),0,6),requested=Get(values,"debris_particles",48).AsDouble()*Get(rule,"amount",1).AsDouble()*intensity*Get(values,style==0?"debris_dust":"debris_chips",1).AsDouble();int amount=(int)Math.Min(Math.Max(Math.Round(requested,MidpointRounding.AwayFromZero),0),Math.Max(0,limit));using var rng=new RandomNumberGenerator{Seed=unchecked((ulong)(impact["seed"].AsInt64()+style*7919L))};for(int i=0;i<amount;i++){var direction=new Vector3(rng.RandfRange(-1,1),rng.RandfRange(.1f,1),rng.RandfRange(-1,1)).Normalized();double speed=Get(rule,"velocity",2).AsDouble()*rng.RandfRange(.35f,1.2f)*Math.Min(3,Math.Sqrt(Math.Max(.01,energy))*.3);var velocity=(direction+impact["normal"].AsVector3()*.6f).Normalized()*(float)speed+impact["velocity"].AsVector3()*.08f;double size=Math.Max(.001,Get(rule,"particle_size",.05).AsDouble())*rng.RandfRange(.6f,1.4f)*(style==0?1+age*.8:1);var basis=Basis.FromEuler(new Vector3(rng.Randf(),rng.Randf(),rng.Randf())*(float)Math.Tau).Scaled(Vector3.One*(float)size);if(style is 2 or 3)basis=basis.Scaled(new Vector3(3,.4f,.4f));var color=Get(rule,"color",new Color(1,1,1,1)).AsColor();color.A*=(float)Math.Pow(Math.Clamp(1-age/life,0,1),.7);result.Add(new Settings{["pose"]=new Transform3D(basis,impact["point"].AsVector3()+velocity*(float)age+Get(rule,"gravity",Vector3.Down).AsVector3()*(float)(age*age*.5)),["color"]=color});}return result;}
    public Mesh mesh(RefCounted owner,int style){var resources=Map(owner,"resources");if(resources.ContainsKey(style))return resources[style].As<Mesh>();Mesh geometry;var material=new StandardMaterial3D{VertexColorUseAsAlbedo=true,Transparency=BaseMaterial3D.TransparencyEnum.Alpha,Roughness=.5f};if(style==0){geometry=new QuadMesh{Size=Vector2.One};material.BillboardMode=BaseMaterial3D.BillboardModeEnum.Enabled;material.ShadingMode=BaseMaterial3D.ShadingModeEnum.Unshaded;material.NoDepthTest=false;using var image=Image.CreateEmpty(32,32,false,Image.Format.Rgba8);for(int y=0;y<32;y++)for(int x=0;x<32;x++)image.SetPixel(x,y,new Color(1,1,1,(float)Math.Pow(Math.Max(0,1-new Vector2((float)((x-15.5)/15.5),(float)((y-15.5)/15.5)).Length()),1.5)));material.AlbedoTexture=ImageTexture.CreateFromImage(image);}else if(style is 2 or 3)geometry=new BoxMesh();else{geometry=new SphereMesh{Radius=.5f,Height=1,RadialSegments=5,Rings=2};material.Metallic=.5f;}if(style==3)material.ShadingMode=BaseMaterial3D.ShadingModeEnum.Unshaded;geometry.SurfaceSetMaterial(0,material);resources[style]=geometry;return geometry;}
    public void apply(RefCounted owner,RefCounted controller,double time){owner.Set("particle_count",0);int count=0;var used=new Settings();var nodes=Map(owner,"nodes");foreach(var entry in Map(controller,"display_states")){if(count>=8192)break;string actorId=entry.Key.AsString();var events=Get(entry.Value.AsGodotDictionary(),"destruction_events",new GArray()).AsGodotArray();if(events.Count==0)continue;var actor=Map(controller,"prototypes")[entry.Key].AsGodotDictionary()["actor"].As<Resource>();var values=_animation.sampled_values(actor,controller.Call("_local",actor,time).AsDouble());var runtime=controller.Call("_runtime",actorId).AsGodotObject() as Node3D;if(runtime==null||!runtime.Get("active").AsBool()||!Get(values,"debris_vfx_enabled",true).AsBool())continue;var rules=this.rules(values);for(int index=0;index<rules.Count;index++){var rule=rules[index].AsGodotDictionary();var points=new GArray();foreach(var value in events){foreach(var particle in particles(value.AsGodotDictionary(),rule,values,time,Math.Max(0,Math.Min(512,8192-count-points.Count))))points.Add(particle);if(points.Count+count>=8192)break;}if(points.Count==0)continue;string key=actorId+":"+index;used[key]=true;if(!nodes.ContainsKey(key)){var node=new MultiMeshInstance3D{Name="DestructionEventParticles"};runtime.AddChild(node);node.TopLevel=true;node.GlobalTransform=Transform3D.Identity;node.Layers=1;node.CastShadow=GeometryInstance3D.ShadowCastingSetting.Off;node.Multimesh=new MultiMesh{TransformFormat=MultiMesh.TransformFormatEnum.Transform3D,UseColors=true};nodes[key]=node;}var visual=nodes[key].As<MultiMeshInstance3D>();visual.Multimesh.Mesh=mesh(owner,Get(rule,"style",0).AsInt32());visual.Multimesh.InstanceCount=points.Count;visual.Show();for(int i=0;i<points.Count;i++){var point=points[i].AsGodotDictionary();visual.Multimesh.SetInstanceTransform(i,point["pose"].AsTransform3D());visual.Multimesh.SetInstanceColor(i,point["color"].AsColor());}count+=points.Count;owner.Set("particle_count",count);}}foreach(var entry in nodes)if(!used.ContainsKey(entry.Key))entry.Value.As<Node3D>().Hide();}
}
